package org.ruoyi.ipd.agent.kernel;
import io.agentscope.core.tool.*;import io.agentscope.core.message.*;import io.agentscope.core.permission.*;import java.util.*;import java.util.concurrent.atomic.*;import reactor.core.publisher.Mono;import static org.mockito.Mockito.*;import org.ruoyi.ipd.service.IpdCopilotAccess;import org.ruoyi.ipd.security.IpdActor;
public class GGovernanceProbe {static ToolBase tool(String n){var t=mock(ToolBase.class);when(t.getName()).thenReturn(n);when(t.getDescription()).thenReturn("safe-probe");when(t.getParameters()).thenReturn(Map.of("type","object"));when(t.checkPermissions(any(),any())).thenReturn(Mono.just(PermissionDecision.allow("safe")));when(t.callAsync(any())).thenReturn(Mono.just(ToolResultBlock.text("synthetic-result")));return t;}static ToolCallParam param(String n){return ToolCallParam.builder().toolUseBlock(ToolUseBlock.builder().id("g-call").name(n).input(Map.of()).content("{}").build()).input(Map.of()).build();} public static void main(String[]a){var sink=mock(ProjectAgentEventSink.class);var gov=new ProjectAgentOfficialToolGovernance(sink);var tk=new Toolkit();var t=tool("g-tool");tk.registerAgentTool(t);tk.createToolGroup("g-inactive","synthetic",false);tk.addToolToGroup("g-inactive","g-tool");var before=tk.callTool(param("g-tool")).block();System.out.println("INACTIVE_BEFORE_STATE="+before.getState());gov.bind(tk);var after=tk.callTool(param("g-tool")).block();System.out.println("INACTIVE_AFTER_STATE="+after.getState());System.out.println("INACTIVE_GROUP_BYPASS="+(after.getState()!=ToolResultState.ERROR));var ask=tool("g-ask");when(ask.checkPermissions(any(),any())).thenReturn(Mono.just(PermissionDecision.ask("safe")));var wrap=new ProjectAgentOfficialToolGovernance.OwnedTool(ask,sink);System.out.println("ASK_PRESERVED="+(wrap.checkPermissions(Map.of(),null).block().getBehavior()==PermissionBehavior.ASK));boolean denied=false;try{wrap.callAsync(param("g-ask")).block();}catch(IllegalStateException e){denied=true;}System.out.println("ASK_EXECUTION_DENIED="+denied);verify(ask,never()).callAsync(any());var web=tool("web_fetch");var ww=new ProjectAgentOfficialToolGovernance.OwnedTool(web,sink);System.out.println("LOCAL_WEB_DENIED="+(ww.checkPermissions(Map.of("url","http://127.0.0.1:16039"),null).block().getBehavior()==PermissionBehavior.DENY));var access=mock(IpdCopilotAccess.class);var actor=mock(IpdActor.class);var guard=new ProjectAgentRuntimeAccess(access,actor,123L);when(access.requireVisible(actor,123L)).thenReturn("tenant").thenThrow(new IllegalStateException("revoked"));var bs=mock(ProjectAgentEventSink.class);doAnswer(i->{guard.requireAuthorized();return null;}).when(bs).requireActiveOwnership();var bt=tool("g-member");var bw=new ProjectAgentOfficialToolGovernance.OwnedTool(bt,bs);bw.checkPermissions(Map.of(),null).block();boolean revoked=false;try{bw.checkPermissions(Map.of(),null).block();}catch(IllegalStateException e){revoked=true;}System.out.println("B_ADAPTER_REVOKED_SECOND_PERMISSION="+revoked);verify(access,times(2)).requireVisible(actor,123L);System.out.println("MAIN_MEMBER_CALLBACK_PRESENT=false");for(var behavior:List.of(PermissionBehavior.ASK,PermissionBehavior.DENY)){var state=io.agentscope.core.state.AgentState.builder().build();var pc=PermissionContextState.builder().build();if(behavior==PermissionBehavior.ASK)pc=PermissionContextState.builder().addAskRule("write_file",new PermissionRule("write_file",null,behavior,"owner-rule")).build();else pc=PermissionContextState.builder().addDenyRule("write_file",new PermissionRule("write_file",null,behavior,"owner-rule")).build();state.setPermissionContext(ProjectAgentOfficialPermissions.extend(pc));var agent=mock(io.agentscope.core.agent.Agent.class);when(agent.getAgentState()).thenReturn(state);var tt=tool("write_file");var tw=new ProjectAgentOfficialToolGovernance.OwnedTool(tt,sink);boolean blocked=false;try{tw.callAsync(ToolCallParam.builder(param("write_file")).agent(agent).build()).block();}catch(IllegalStateException e){blocked=true;}System.out.println("EXISTING_"+behavior+"_RULE_STILL_BLOCKS="+blocked);verify(tt,never()).callAsync(any());}var execAccess=mock(IpdCopilotAccess.class);when(execAccess.requireVisible(actor,123L)).thenReturn("tenant").thenThrow(new IllegalStateException("revoked-between-permission-and-execution"));var eg=new ProjectAgentRuntimeAccess(execAccess,actor,123L);var es=mock(ProjectAgentEventSink.class);doAnswer(i->{eg.requireAuthorized();return null;}).when(es).requireActiveOwnership();var et=tool("g-execution");var ew=new ProjectAgentOfficialToolGovernance.OwnedTool(et,es);ew.checkPermissions(Map.of(),null).block();boolean executionRevoked=false;try{ew.callAsync(param("g-execution")).block();}catch(IllegalStateException e){executionRevoked=true;}System.out.println("B_ADAPTER_REVOKED_BEFORE_EXECUTION="+executionRevoked);verify(et,never()).callAsync(any());}}
